import{_ as a,o as t,c as r,a5 as i}from"./chunks/framework.BF53ZjCA.js";const h=JSON.parse('{"title":"Silicates — Framework (Tectosilicates)","description":"","frontmatter":{"title":"Silicates — Framework (Tectosilicates)","mineralGroup":"silicates-framework"},"headers":[],"relativePath":"classification/mineral-groups/silicates-framework.md","filePath":"classification/mineral-groups/silicates-framework.md","lastUpdated":1790876393000}'),s={name:"classification/mineral-groups/silicates-framework.md"};function l(o,e,n,c,d,m){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="silicates-—-framework-tectosilicates" tabindex="-1">Silicates — Framework (Tectosilicates) <a class="header-anchor" href="#silicates-—-framework-tectosilicates" aria-label="Permalink to &quot;Silicates — Framework (Tectosilicates)&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Framework silicates have a SiO₂ / Al₂O₃ molar ratio around 3:1–6:1. The most important gem-bearing family is the feldspar group (moonstone, labradorite, sunstone, amazonite); zeolites are occasionally cut. Feldspars account for ~60% of Earth&#39;s crustal mineral volume.</p><h2 id="formula-class" tabindex="-1">Formula Class <a class="header-anchor" href="#formula-class" aria-label="Permalink to &quot;Formula Class&quot;">​</a></h2><p>M(Al,Si)₄O₈</p><h2 id="crystal-structure" tabindex="-1">Crystal Structure <a class="header-anchor" href="#crystal-structure" aria-label="Permalink to &quot;Crystal Structure&quot;">​</a></h2><p>[SiO₄]⁴⁻ tetrahedra share all four oxygens, forming a 3D infinite framework. In feldspars, Si⁴⁺ / Al³⁺ substitution occurs at tetrahedral sites; alkali / alkaline-earth cations fill structural cavities. The Si/Al ratio and cation type determine the species.</p><h2 id="representative-gem-species" tabindex="-1">Representative Gem Species <a class="header-anchor" href="#representative-gem-species" aria-label="Permalink to &quot;Representative Gem Species&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Gem</th><th>Formula</th><th>Subgroup</th></tr></thead><tbody><tr><td>Moonstone / 月光石</td><td>(K,Na)AlSi₃O₈</td><td>orthoclase</td></tr><tr><td>Labradorite / 拉长石</td><td>(Ca,Na)(Si,Al)₄O₈</td><td>plagioclase</td></tr><tr><td>Sunstone / 日光石</td><td>(Na,Ca)(Si,Al)₄O₈ + Cu/Fe</td><td>plagioclase</td></tr><tr><td>Amazonite / 天河石</td><td>KAlSi₃O₈</td><td>microcline</td></tr><tr><td>Spectrolite / 光谱石</td><td>(Ca,Na)(Si,Al)₄O₈</td><td>plagioclase</td></tr><tr><td>Orthoclase / 正长石</td><td>KAlSi₃O₈</td><td>orthoclase</td></tr></tbody></table><p><em>See the <a href="./intro.html">mineral group overview</a>.</em></p><aside class="gem-reference-block" aria-labelledby="gem-reference-title"><p class="gem-reference-block__eyebrow">SOURCE TRACE</p><h2 id="gem-reference-title">References &amp; Evidence Boundary</h2><p class="gem-reference-block__intro">This page supports learning and retrieval; the sources document the knowledge basis and do not make this page sufficient for identifying a specific specimen.</p><ul><li><a href="https://elearning-samples.gia.edu/Gem_Identification/Page5.html" target="_blank" rel="noreferrer">GIA: Gem Species, Varieties, and Groups</a><span>Relationships among mineral species, gem varieties, and mineral groups</span><small>Open source ↗</small></li><li><a href="https://www.mindat.org/" target="_blank" rel="noreferrer">Mindat mineral database</a><span>Mineral names, chemistry, and classification lookup</span><small>Open source ↗</small></li></ul></aside>',11)])])}const u=a(s,[["render",l]]);export{h as __pageData,u as default};
